94	    /** The grade a person (sheet, person id) has on a date: the one with the latest from-date on
95	     *  or before it, the first one they were given applying from the beginning of time. */
96	    private static final String GRADE_ON = "(SELECT g.grade FROM person_grade g WHERE g.sheet_id = ? AND g.person_id = ?"
97	            + " AND (g.from_date IS NULL OR g.from_date <= CAST(? AS DATE)) ORDER BY g.from_date DESC NULLS LAST LIMIT 1)";
