116	    /** A claim on the sheet; null when the sheet has no such claim. */
117	    public Claim find(String sheetId, long claimId) {
118	        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW,
119	                sheetId, claimId);
