123	    /** Move a claim to a status, only when it is now in one of {@code from}; false when it is not. */
124	    public boolean changeStatus(String sheetId, long claimId, List<String> from, String to) {
125	        String in = String.join(", ", from.stream().map(s -> "?").toList());
126	        List<Object> args = new ArrayList<>(List.of(to, claimId, sheetId));
127	        args.addAll(from);
128	        return jdbc.update("UPDATE claim SET status = ? WHERE id = ? AND sheet_id = ? AND status IN (" + in + ")",
129	                args.toArray()) > 0;
130	    }
