132	    /** Give an opened claim the sheet's next number. The sheet's row stays locked until the
133	     *  transaction commits, so two claims opened at once get consecutive numbers. */
134	    public String number(String sheetId, long claimId) {
135	        jdbc.update("UPDATE sheet SET claim_number = claim_number + 1 WHERE id = ?", sheetId);
136	        Long next = jdbc.queryForObject("SELECT claim_number FROM sheet WHERE id = ?", Long.class, sheetId);
137	        String number = String.valueOf(next);
138	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
139	        return number;
140	    }
