142	    /** Whether claims opened now are numbered per period: the sheet's period numbering from-date is set
143	     *  and its today is on or after it. */
144	    public boolean numbersPerPeriod(String sheetId) {
145	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ? AND period_numbering_from IS NOT NULL"
146	                + " AND today >= period_numbering_from", Integer.class, sheetId);
147	        return n != null && n > 0;
148	    }
