150	    /** Give an opened claim the next number in the sequence of the period its date falls in,
151	     *  <period name>-<n>, or X-<n> when it is in no period. The sheet's row is locked first, so two
152	     *  claims opened at once get consecutive numbers. */
153	    public String numberInPeriod(String sheetId, long claimId, LocalDate date) {
154	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id = ?", sheetId);
155	        List<Object[]> period = jdbc.query("SELECT id, name FROM period WHERE sheet_id = ? AND from_date <= ?"
156	                + " AND to_date >= ? ORDER BY from_date LIMIT 1",
157	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("name") }, sheetId, Date.valueOf(date),
158	                Date.valueOf(date));
159	        String key = period.isEmpty() ? "X" : "P" + period.get(0)[0];
160	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
161	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
162	                sheetId, key) == 0) {
163	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
164	        }
165	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
166	                Long.class, sheetId, key);
167	        String number = prefix + "-" + next;
168	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
169	        return number;
170	    }
