177	    /** A claim's due now: its amount at the rate, in force on the claim's date, for the grade its person
178	     *  had on that date
179	     *  (the one with the latest from-date on or before it; an undated rate applies from the beginning
180	     *  of time), rounded to two decimals by the claim's rounding (see {@link #rounding}), and at least the sheet's floor (a correction's, a
181	     *  negative amount's, has no floor); null when no rate applies. */
182	    public BigDecimal due(String sheetId, Claim claim) {
183	        List<BigDecimal> pct = jdbc.queryForList("SELECT r.pct FROM rate r WHERE r.sheet_id = ? AND r.grade = "
184	                + GRADE_ON + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE))"
185	                + " ORDER BY r.from_date DESC NULLS LAST LIMIT 1", BigDecimal.class, sheetId,
186	                sheetId, claim.personId(), claim.date(), claim.date());
187	        if (pct.isEmpty()) return null;
188	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct.get(0)).movePointLeft(2)
189	                .setScale(2, rounding(sheetId, claim));
190	        return new BigDecimal(claim.amount()).signum() < 0 ? due : due.max(floor(sheetId));
191	    }
192	
193	    /** How a claim's live figures round: half up when the claim is dated before the sheet's policy date
194	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
195	     *  claim it corrects (its person's claim with that number), not its own. */
196	    public RoundingMode rounding(String sheetId, Claim claim) {
197	        String date = claim.date();
198	        if (claim.corrects() != null) {
199	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
200	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
201	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
202	        }
203	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
204	                Date.class, sheetId);
205	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
206	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
207	                : RoundingMode.HALF_EVEN;
208	    }
209	
210	    /** The sheet's floor: the least a live due can be (two decimals). */
211	    public BigDecimal floor(String sheetId) {
212	        List<BigDecimal> found = jdbc.queryForList("SELECT floor FROM sheet WHERE id = ?", BigDecimal.class, sheetId);
213	        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE.setScale(2) : found.get(0).setScale(2);
214	    }
215	
216	    /** A claim's figure now: the due fixed when it was settled, else the one its last statement bound
217	     *  it to (not while PENDING), else its live due; null when it has none. */
218	    public BigDecimal figure(String sheetId, Claim claim) {
219	        if (claim.due() != null) return new BigDecimal(claim.due());
220	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
221	        return due(sheetId, claim);
222	    }
223	
224	    /** A claim's due now: its figure, plus, while it is overdue (OPEN or PENDING and its due-by — fixed when it was
225	     *  created — before the sheet's today), the sheet's late percent of that figure for every full
226	     *  30 days it is overdue, rounded to two decimals by the claim's rounding. A statement never binds the charge:
227	     *  it keeps following the sheet's today until settling freezes it in. A correction (a negative amount)
228	     *  has no late charge. Null when it has no figure. */
229	    public BigDecimal dueNow(String sheetId, Claim claim) {
230	        BigDecimal figure = figure(sheetId, claim);
231	        if (figure == null || !claim.open() || new BigDecimal(claim.amount()).signum() < 0) {
232	            return figure;
233	        }
234	        List<Object[]> found = jdbc.query("SELECT today, late_pct FROM sheet WHERE id = ?",
235	                (rs, i) -> new Object[] { rs.getDate("today").toLocalDate(), rs.getBigDecimal("late_pct") }, sheetId);
236	        if (found.isEmpty()) return figure;
237	        LocalDate today = (LocalDate) found.get(0)[0];
238	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
239	        BigDecimal pct = (BigDecimal) found.get(0)[1];
240	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
241	        if (periods == 0 || pct == null || pct.signum() == 0) return figure;
242	        BigDecimal charge = figure.multiply(pct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
243	                .setScale(2, rounding(sheetId, claim));
244	        return figure.add(charge);
245	    }
