267	    /** Move a DRAFT, OPEN or PENDING claim to another person: it is unbound from its last statement (live
268	     *  again) and listed as its new person's newest claim; false when the sheet has no such claim in those statuses. */
269	    public boolean reassign(String sheetId, long claimId, long personId) {
