275	    /** Fix a settled claim's due. */
276	    public void settleDue(String sheetId, long claimId, BigDecimal due) {
277	        jdbc.update("UPDATE claim SET settled_due = ? WHERE id = ? AND sheet_id = ?", due, claimId, sheetId);
278	    }
