280	    /** The name of a person on the sheet. */
281	    public String personName(String sheetId, long personId) {
282	        return jdbc.queryForObject("SELECT name FROM person WHERE sheet_id = ? AND id = ?",
283	                String.class, sheetId, personId);
284	    }
285	
286	    /** Whether the person has a SETTLED claim with this number on the sheet. */
287	    public boolean settledOf(String sheetId, long personId, String number) {
288	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
289	                + " AND claim_no = ? AND status = 'SETTLED'", Integer.class, sheetId, personId, number);
290	        return n != null && n > 0;
291	    }
292	
293	    /** The due-by of a claim created now for a person with a date: the date plus the terms of the grade the
294	     *  person has on it, else the sheet's terms. */
295	    public LocalDate dueBy(String sheetId, long personId, LocalDate date) {
296	        List<Integer> own = jdbc.queryForList("SELECT t.terms FROM grade_terms t WHERE t.sheet_id = ? AND t.grade = "
297	                + GRADE_ON, Integer.class, sheetId, sheetId, personId, date.toString());
298	        if (!own.isEmpty()) return date.plusDays(own.get(0));
299	        List<Integer> sheet = jdbc.queryForList("SELECT terms FROM sheet WHERE id = ?", Integer.class, sheetId);
300	        return date.plusDays(sheet.isEmpty() ? 14 : sheet.get(0));
301	    }
302	
303	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
304	        LocalDate dueBy = dueBy(sheetId, personId, date);
305	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
306	        jdbc.update(c -> {
307	            PreparedStatement ps = c.prepareStatement(
308	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
309	                    new String[] { "id" });
310	            ps.setString(1, sheetId);
311	            ps.setLong(2, personId);
312	            ps.setBigDecimal(3, amount);
313	            ps.setDate(4, Date.valueOf(date));
314	            ps.setString(5, note);
315	            ps.setString(6, corrects);
316	            ps.setDate(7, Date.valueOf(dueBy));
317	            return ps;
318	        }, keys);
319	        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects,
320	                dueBy.toString());
321	    }
322	
323	    /** Change a DRAFT claim's amount, date, note and the number it corrects; false when the sheet has no
324	     *  such draft claim. */
325	    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, String note, String corrects) {
326	        return jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, corrects = ? WHERE id = ?"
327	                + " AND sheet_id = ? AND status = 'DRAFT'",
328	                amount, Date.valueOf(date), note, corrects, claimId, sheetId) > 0;
329	    }
330	
331	    /** An amount as shown: two decimals, a dot, no grouping. */
332	    static String money(BigDecimal amount) {
333	        return amount.setScale(2).toPlainString();
334	    }
335	
336	    /** A fixed due as shown, or null when there is none. */
337	    static String dueOf(BigDecimal due) {
338	        return due == null ? null : money(due);
339	    }
