433	/** Open the selected claims together, in list order (people in the order they were added, each
434	 *  person's claims newest first), each numbered as it is opened. A claim that cannot be opened (no
435	 *  such claim, not a DRAFT, dated in a closed period) is left as it is and counted as refused. */
436	public class BulkOpenClaims {
437	    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
438	            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
439	            SettingsRepository settings, Audit audit, Rollup rollup, Out<BulkOpenResult> result) throws BadRequestException {
440	        String by = CurrentUser.require(connection);
441	        String id = sheetId == null ? "" : sheetId.trim();
442	        Set<Long> selected = new LinkedHashSet<>();
443	        if (request != null && request.claimIds() != null) {
444	            for (Long cid : request.claimIds()) {
445	                if (cid != null) selected.add(cid);
446	            }
447	        }
448	        if (selected.isEmpty()) {
449	            throw new BadRequestException("select at least one claim");
450	        }
451	        List<Claim> found = new ArrayList<>();
452	        int refused = 0;
453	        for (Long cid : selected) {
454	            Claim c = repository.find(id, cid);
455	            if (c == null) refused++;
456	            else found.add(c);
457	        }
458	        found.sort(Comparator.comparingLong(Claim::personId).thenComparing(Claim::id, Comparator.reverseOrder()));
459	        int opened = 0;
460	        for (Claim c : found) {
461	            try {
462	                ClaimStatusChange.apply(id, c.id(), "open", by, repository, periods, settings, audit, rollup);
463	                opened++;
464	            } catch (BadRequestException e) {
465	                refused++;
466	            }
467	        }
468	        result.set(new BulkOpenResult(opened, refused));
469	    }
470	}
