483	/** A claim's status change (open, settle, approve, reject or void), shared by the single and the bulk actions. Every
484	 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
485	final class ClaimStatusChange {
486	    private ClaimStatusChange() {
487	    }
488	
489	    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
490	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
491	        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup);
492	    }
493	
494	    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
495	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
496	        String to;
497	        List<String> from;
498	        String event;
499	        switch (action == null ? "" : action.trim()) {
500	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
501	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
502	            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
503	            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
504	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING"); event = "CLAIM_VOIDED"; }
505	            default -> throw new BadRequestException("no such action");
506	        }
507	        Claim found = repository.find(id, cid);
508	        if (found == null) {
509	            throw new BadRequestException("no such claim");
510	        }
511	        if (!from.contains(found.status())) {
512	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
513	        }
514	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
515	        // Four eyes: whoever opened a claim cannot settle it.
516	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
517	            throw new BadRequestException("the user who opened a claim cannot settle it");
518	        }
519	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
520	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
521	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
522	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
523	            }
524	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
525	                throw new BadRequestException("the user who opened a claim cannot approve it");
526	            }
527	        }
528	        String why = reason == null ? "" : reason.trim();
529	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
530	            throw new BadRequestException("give a reason to reject the claim");
531	        }
532	        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
533	        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
534	        if (to.equals("SETTLED") && found.status().equals("OPEN")
535	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
536	            BigDecimal limit = settings.clerkLimit(id);
537	            BigDecimal now = repository.dueNow(id, found);
538	            if (limit != null && now != null && now.compareTo(limit) > 0) {
539	                to = "PENDING";
540	                event = "CLAIM_PENDING";
541	            }
542	        }
543	        Rollup.Snapshot before = rollup.take(id);
544	        if (!repository.changeStatus(id, cid, from, to)) {
545	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
546	        }
547	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
548	        String number = found.number();
549	        String openedBy = found.openedBy();
550	        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
551	            number = repository.numbersPerPeriod(id)
552	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.date()))
553	                    : repository.number(id, cid);
554	            repository.openedBy(id, cid, by);
555	            openedBy = by;
556	        }
557	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
558	        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
559	        String due = null;
560	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
561	        if (to.equals("SETTLED")) {
562	            BigDecimal now = repository.dueNow(id, found);
563	            repository.settleDue(id, cid, now);
564	            due = ClaimRepository.dueOf(now);
565	            tail = " due=" + (due == null ? "n/a" : due);
566	        }
567	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
568	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy());
569	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
570	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
571	        rollup.record(id, by, before);
572	        return changed;
573	    }
574	}
